def keep_number_groups(value):
    if isinstance(value,str): return value.replace('100 000','100\u00a0000')
    if isinstance(value,list): return [keep_number_groups(item) for item in value]
    if isinstance(value,dict): return {key:keep_number_groups(item) for key,item in value.items()}
    return value
BLOCKS=keep_number_groups(BLOCKS)
